INSERT INTO services (slug, title, description, image, sort_order) VALUES
  ('laser-cutting', 'CNC Laser Cutting', 'Two fiber lasers (3 kW HSG + 1.5 kW Genesis) with 3 m x 1.5 m beds. MS up to 16 mm, SS 12 mm, Aluminium 8 mm, Brass & Copper 4 mm.', '/sites/pslaser/gallery/laser-cutting-bg.jpg', 1),
